@@ -0,0 +1,55 @@
+import { renderHook } from '@testing-library/react';
+
+import { type DataSourceInstanceListItem, type DataSourcePluginMeta } from '@grafana/data';
+
+import { getDefaultDataSourceFromList, useDefaultDataSourceFromList } from './defaultDataSource';
+
+function item(overrides: Partial<DataSourceInstanceListItem> & { builtIn?: boolean }): DataSourceInstanceListItem {
+  const { builtIn, ...rest } = overrides;
+  return {
+    uid: 'uid',
+    name: 'name',
+    type: 'prometheus',
+    isDefault: false,
+    meta: { id: rest.type ?? 'prometheus', builtIn } as DataSourcePluginMeta,
+    ...rest,
+  };
+}
+
+const grafana = item({ uid: 'grafana', name: '-- Grafana --', type: 'grafana', builtIn: true });
+const promA = item({ uid: 'prom-a', name: 'Prom A' });
+const promB = item({ uid: 'prom-b', name: 'Prom B' });
+const loki = item({ uid: 'loki', name: 'Loki', type: 'loki', isDefault: true });
+
+describe('getDefaultDataSourceFromList', () => {
+  it('returns undefined for an empty or missing list', () => {
+    expect(getDefaultDataSourceFromList([])).toBeUndefined();
+    expect(getDefaultDataSourceFromList(undefined)).toBeUndefined();
+    expect(getDefaultDataSourceFromList(null)).toBeUndefined();
+  });
+
+  it('returns the organization default when it is in the list', () => {
+    expect(getDefaultDataSourceFromList([grafana, promA, loki, promB])).toBe(loki);
+  });
+
+  it('returns the first non built-in instance of a subset without the organization default', () => {
+    expect(getDefaultDataSourceFromList([grafana, promA, promB])).toBe(promA);
+  });
+
+  it('returns the first instance when the list only contains built-ins', () => {
+    const mixed = item({ uid: 'mixed', name: '-- Mixed --', type: 'mixed', builtIn: true });
+    expect(getDefaultDataSourceFromList([grafana, mixed])).toBe(grafana);
+  });
+});
+
+describe('useDefaultDataSourceFromList', () => {
+  it('returns the default of the given list and updates when the list changes', () => {
+    const { result, rerender } = renderHook(({ items }) => useDefaultDataSourceFromList(items), {
+      initialProps: { items: [promA, loki] },
+    });
+    expect(result.current).toBe(loki);
+
+    rerender({ items: [promB, promA] });
+    expect(result.current).toBe(promB);
+  });
+});
