--- /dev/null
+++ b/packages/grafana-runtime/src/utils/defaultDataSource.ts
@@ -0,0 +1,56 @@
+import { useMemo } from 'react';
+
+/**
+ * The minimal shape needed to pick a default. Satisfied by both `DataSourceInstanceListItem`
+ * and `DataSourceInstanceSettings`.
+ *
+ * @public
+ */
+export interface DefaultDataSourceCandidate {
+  isDefault?: boolean;
+  meta: { builtIn?: boolean };
+}
+
+/**
+ * Pick the default data source from a list of data source instances.
+ *
+ * - When the list contains the organization default (`isDefault: true`), it is returned. So
+ *   passing the full list of data sources yields the organization default.
+ * - Otherwise (e.g. a list filtered to a single type that does not include the organization
+ *   default), the first non built-in instance (not `-- Grafana --`, `-- Mixed --`, ...) is returned.
+ * - If the list only contains built-in data sources, the first one is returned.
+ * - Returns `undefined` for an empty list.
+ *
+ * This is a plain function, so it can be used outside of React rendering. Inside components use
+ * {@link useDefaultDataSourceFromList}.
+ *
+ * @example
+ * ```ts
+ * const prometheusList = await getDataSourceSrv().getList({ type: 'prometheus' });
+ * const defaultPrometheus = getDefaultDataSourceFromList(prometheusList);
+ * ```
+ *
+ * @public
+ */
+export function getDefaultDataSourceFromList<T extends DefaultDataSourceCandidate>(
+  items: readonly T[] | null | undefined
+): T | undefined {
+  if (!items || items.length === 0) {
+    return undefined;
+  }
+
+  return items.find((item) => item.isDefault) ?? items.find((item) => !item.meta.builtIn) ?? items[0];
+}
+
+/**
+ * React hook wrapping {@link getDefaultDataSourceFromList}. The result is memoized on the
+ * `items` array reference, so pass a stable array (e.g. the `items` returned by a data source
+ * list hook) to avoid recomputing on every render.
+ *
+ * @public
+ */
+export function useDefaultDataSourceFromList<T extends DefaultDataSourceCandidate>(
+  items: readonly T[] | null | undefined
+): T | undefined {
+  return useMemo(() => getDefaultDataSourceFromList(items), [items]);
+}
